-- GENERATED by tools/build.py. Do not edit.
-- Source of truth is queries/*.sql; edit there and rebuild.
-- Columns, in order: kind, id, ver, loc, extra, perms
--
-- PLATFORM: darwin. Run this only on darwin. The tables named here do not all
-- exist elsewhere, and osqueryi given a missing table returns "[\n\n]" -- valid,
-- empty, entirely plausible JSON -- and exits 1. Every other artifact in dist/ is for a
-- different platform and is NOT a superset of this one. bin/discover picks by `uname -s`.

-- from apps.sql
SELECT 'app' AS kind, bundle_identifier AS id, bundle_short_version AS ver, path AS loc,
       '' AS extra, '' AS perms
  FROM apps

UNION ALL

-- from browser.sql
SELECT 'ext' AS kind, identifier AS id, version AS ver, profile_path AS loc,
       browser_type AS extra,
       permissions
         || CASE WHEN manifest_json LIKE '%<all_urls>%' THEN ',<all_urls>' ELSE '' END
         || CASE WHEN referenced = 0 THEN ',unreferenced'
                 WHEN from_webstore != 'true'
                   THEN ',sideloaded:' || IFNULL(manifest_hash, '')
                 ELSE '' END
         AS perms
  FROM (SELECT uid FROM users
        UNION
        SELECT uid FROM file
         WHERE path LIKE '/home/%/' OR path = '/root/' OR path LIKE '/Users/%/') u
       CROSS JOIN chrome_extensions USING (uid)

UNION ALL

-- from filesystem.sql
SELECT 'file' AS kind, path AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/Users/%/.local/bin/%'
UNION ALL
-- STATE DIRECTORIES, the most install-route-independent signal available: a cask, an npm
-- global, `curl install.sh | bash` and a source checkout all converge on the same dotdir
-- the first time the agent runs. Package-manager branches see only the route that was
-- used, and see nothing at all for a source build.
--
-- THE TRAILING SLASH IS LOAD-BEARING. osquery translates LIKE into its glob engine, where
-- a directory must be addressed with a trailing slash:
--     path LIKE '/Users/%/.claude'   -> 0 rows, no error
--     path LIKE '/Users/%/.claude/'  -> the directory
-- Same silent-zero shape as the JOIN and the one-% glob. Do not "tidy" the slash away.
--
-- Every top-level dotdir now, not four named ones. 47 on a loaded reference Mac, which is
-- affordable, and it means a new agent's state directory is evidence on the first scan
-- rather than after a fleet redeploy.
--
-- `.` AND `..` COME BACK FROM THIS GLOB SHAPE. Measured on a reference Mac: 4 of the 47
-- dotdir rows were /Users/x/./ and /Users/x/../, which can never match anything and
-- arrive as unmatched rows a reader has to dismiss by hand. Found while writing the Linux
-- twin of this branch and fixed in both, so the two files do not differ for a reason
-- nobody could explain.
SELECT 'file', path, '', path, '', '' FROM file
  WHERE path LIKE '/Users/%/.%/'
    AND path NOT LIKE '%/./'
    AND path NOT LIKE '%/../'
UNION ALL
-- PYTHON-PACKAGED AGENTS. python_packages is deliberately absent from this query (15.6s,
-- no WHERE push-down), which would leave pipx, uv and pip --user installs invisible. That
-- is not a small corner: aider, litellm, crewai, langgraph, open-interpreter and most MCP
-- servers ship on PyPI first and some ONLY there.
--
-- The design justified dropping python_packages as contributing "zero Tier A matches",
-- but that was measured on a machine with none of them installed -- absence of evidence
-- read as evidence of absence.
--
-- So glob the INSTALL LOCATIONS instead of querying the slow table. Both managers give
-- each tool its own directory named for the package, which is precise, bounded and free.
-- These globs were already product-free and are unchanged.
SELECT 'file', path, '', path, '', '' FROM file
  WHERE path LIKE '/Users/%/.local/pipx/venvs/%/'
     OR path LIKE '/Users/%/.local/share/uv/tools/%/'
-- KNOWN GAP, deliberately not covered: packages executed via `npx`/`bunx` and never
-- installed. They land in a content-addressed cache, /Users/x/.npm/_npx/<hash>/
-- node_modules/<pkg>, where the invoked package is indistinguishable BY PATH from its
-- transitive dependencies. Measured on the reference Mac: globbing that cache generically
-- returns 1938 rows, and the scoped-only variant returns 123 which are almost entirely
-- @aws-sdk, @babel and @nodelib. The old branch avoided this only by naming two packages
-- outright, which is the practice this file exists to remove.
--
-- An agent run through npx still creates its state dotdir on first run and is caught by
-- the branch above. That reasoning is UNVERIFIED -- it has not been exercised against a
-- real npx-launched agent -- so it is recorded here as a gap rather than a mitigation.
-- Scenario 55-openclaw-npm is where it would be proven.

UNION ALL

-- from homebrew.sql
SELECT 'brew' AS kind, name AS id, version AS ver, path AS loc,
       type AS extra, '' AS perms
  FROM homebrew_packages

UNION ALL

-- from jetbrains.sql
SELECT 'jbplugin' AS kind, regex_match(path, '([^/]+)/?$', 1) AS id, version AS ver,
       path AS loc, vendor AS extra, '' AS perms
  FROM (SELECT uid FROM users
        UNION
        SELECT uid FROM file
         WHERE path LIKE '/home/%/' OR path = '/root/' OR path LIKE '/Users/%/') u
       CROSS JOIN jetbrains_plugins USING (uid)

UNION ALL

-- from native-messaging.sql
SELECT 'nmh' AS kind, filename AS id, '' AS ver, path AS loc,
       '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/Users/%/Library/Application Support/%/NativeMessagingHosts/%.json'
    AND filename != 'com.apple.passwordmanager.json'
UNION ALL
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/Users/%/Library/Application Support/%/%/NativeMessagingHosts/%.json'
    AND filename != 'com.apple.passwordmanager.json'
UNION ALL
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/Library/%/%/NativeMessagingHosts/%.json'
    AND filename != 'com.apple.passwordmanager.json'

UNION ALL

-- from packages.sql
SELECT 'npm' AS kind, name AS id, version AS ver, path AS loc, '' AS extra, '' AS perms
  FROM npm_packages
  WHERE path NOT LIKE '%/node_modules/%/node_modules/%'
UNION ALL
-- BUN GLOBALS. npm_packages searches a fixed list of prefixes -- npm, nvm, asdf, fnm,
-- mise, volta -- and never ~/.bun, so `bun add -g` was invisible (npm_packages.cpp at
-- 5.23.1). Its `directory` constraint replaces that list and means "the directory that
-- holds node_modules", and the join pushes it down once per home. The homes come from the
-- two places queries/vscode.sql takes its uids from, for the reason given there, and a
-- directory row from `file` ends in '/', so it is trimmed before the suffix goes on.
--
-- `extra` IS 'bun' because bun HOISTS: a global's dependencies sit flat beside it in the
-- one node_modules, so the structural predicate cannot drop them, and every one is a row.
-- A reader of unmatched rows needs to know why several packages arrived with one global.
--
-- Not covered: a global directory moved by BUN_INSTALL_GLOBAL_DIR or bunfig's globalDir.
SELECT 'npm', np.name, np.version, np.path, 'bun', ''
  FROM (SELECT directory AS home FROM users
        UNION
        SELECT rtrim(path, '/') FROM file
         WHERE path LIKE '/home/%/' OR path = '/root/' OR path LIKE '/Users/%/') h
       CROSS JOIN npm_packages np ON np.directory = h.home || '/.bun/install/global'
  WHERE np.path NOT LIKE '%/node_modules/%/node_modules/%'

UNION ALL

-- from ports.sql
SELECT 'port' AS kind, CAST(lp.port AS TEXT) AS id, '' AS ver, p.path AS loc,
       lp.address AS extra, '' AS perms
  FROM listening_ports lp JOIN processes p USING (pid)
  WHERE lp.port > 0

UNION ALL

-- from running-darwin.sql
SELECT 'proc' AS kind, pl.value AS id, '' AS ver, x.app AS loc, '' AS extra, '' AS perms
  FROM (SELECT DISTINCT substr(path, 1, instr(path, '.app/') + 3) AS app
          FROM processes WHERE path LIKE '%.app/Contents/MacOS/%') x
       CROSS JOIN plist pl ON pl.path = x.app || '/Contents/Info.plist'
  WHERE pl.key = 'CFBundleIdentifier'

UNION ALL

-- from running.sql
SELECT 'proc' AS kind,
       regex_match(exe || ' ' || cmdline,
                   'node_modules/((?:@[A-Za-z0-9][A-Za-z0-9._-]*/)?[A-Za-z0-9][A-Za-z0-9._-]*)', 1) AS id,
       '' AS ver, exe AS loc, '' AS extra, '' AS perms
  FROM (SELECT cmdline,
               CASE WHEN path != '' THEN path
                    ELSE substr(cmdline, 1, instr(cmdline || ' ', ' ') - 1) END AS exe
          FROM processes) p
  WHERE (exe LIKE '%/node_modules/%'
         OR ((exe LIKE '%/node' OR exe LIKE '%/nodejs' OR exe LIKE '%/bun' OR exe LIKE '%/deno'
              OR exe IN ('node', 'nodejs', 'bun', 'deno'))
             AND cmdline LIKE '%node_modules/%'))
    AND regex_match(exe || ' ' || cmdline,
                    'node_modules/((?:@[A-Za-z0-9][A-Za-z0-9._-]*/)?[A-Za-z0-9][A-Za-z0-9._-]*)', 1) IS NOT NULL
  -- One row per package and executable, however many workers it runs. GROUP BY rather than
  -- DISTINCT, because lint and tools/build.py find a branch's kind as `SELECT '<kind>'`.
  GROUP BY id, loc
UNION ALL
-- RUNNING FROM A HOME DIRECTORY, by executable path. Claude Code's native install runs from
-- ~/.local/share/claude/versions/<version>, not from the ~/.local/bin/claude link the
-- `binaries` route names, so the process_paths route carries its own value. Read off a
-- running `claude mcp serve` on 2026-10-07.
--
-- `path` ONLY, with no argv[0] stand-in: where the path is unreadable, argv[0] is the
-- launcher a user typed, which no process_paths value names. GROUP BY folds the sessions
-- of one binary into one row.
SELECT 'proc', path, '', path, '', ''
  FROM processes
  WHERE path LIKE '/Users/%/%' OR path LIKE '/home/%/%' OR path LIKE '/root/%'
  GROUP BY path

UNION ALL

-- from runtime.sql
SELECT 'daemon' AS kind, label AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM launchd
  WHERE label NOT LIKE 'com.apple.%'

UNION ALL

-- from vscode.sql
SELECT 'vscodeext' AS kind, name AS id, version AS ver, path AS loc,
       vscode_edition AS extra, '' AS perms
  FROM (SELECT uid FROM users
        UNION
        SELECT uid FROM file
         WHERE path LIKE '/home/%/' OR path = '/root/' OR path LIKE '/Users/%/') u
       CROSS JOIN vscode_extensions USING (uid);
